import { isClosedStatus, TaskStatus, type WorkTask } from "../../types/work-projects"
import { RequestStatus, type ClientRequest } from "../../types/work-requests"

/**
 * Rules for client requests (P3): where a request sits in the team's inbox,
 * and what the client is told about it in the portal.
 */

export const MAX_REQUEST_TITLE = 120
export const MAX_REQUEST_DETAILS = 2000

/** A snoozed request comes back as new on its day. */
export function requestState(r: Pick<ClientRequest, "status" | "snoozedUntil">, today: string): RequestStatus {
  if (r.status === RequestStatus.SNOOZED && (!r.snoozedUntil || r.snoozedUntil <= today)) return RequestStatus.NEW
  return r.status
}

/** New and snoozed requests are still to answer; the others are decided. */
export const isOpenRequest = (r: Pick<ClientRequest, "status">) => r.status === RequestStatus.NEW || r.status === RequestStatus.SNOOZED

/** Requests waiting for an answer today (new, or back from snooze). */
export const waitingRequests = <T extends Pick<ClientRequest, "status" | "snoozedUntil">>(list: T[], today: string) =>
  list.filter((r) => requestState(r, today) === RequestStatus.NEW)

/** The next number in the workspace: REQ-001, REQ-002… */
export function nextRequestNumber(existing: Pick<ClientRequest, "number">[]) {
  const max = existing.reduce((m, r) => Math.max(m, Number(r.number.replace(/\D/g, "")) || 0), 0)
  return `REQ-${String(max + 1).padStart(3, "0")}`
}

export type ClientRequestView = "received" | "later" | "planned" | "working" | "done" | "declined" | "alreadyPlanned"

/**
 * What the portal says about a request: received or later while the team
 * decides, then planned, in progress or done as its task moves; declined
 * (with the reason) or already planned (a duplicate).
 */
export function clientView(r: ClientRequest, tasks: Pick<WorkTask, "id" | "status">[], today: string): ClientRequestView {
  const state = requestState(r, today)
  if (state === RequestStatus.NEW) return "received"
  if (state === RequestStatus.SNOOZED) return "later"
  if (state === RequestStatus.REJECTED) return "declined"
  const task = tasks.find((t) => t.id === (state === RequestStatus.DUPLICATE ? r.duplicateOfTaskId : r.taskId))
  if (!task) return state === RequestStatus.DUPLICATE ? "alreadyPlanned" : "planned"
  if (task.status === TaskStatus.DONE) return "done"
  if (task.status === TaskStatus.CANCELLED) return "declined"
  if (isClosedStatus(task.status) || task.status === TaskStatus.TODO) return state === RequestStatus.DUPLICATE ? "alreadyPlanned" : "planned"
  return "working"
}

/** Days since the request arrived, for the inbox. */
export const requestAgeDays = (r: Pick<ClientRequest, "createdAt">, today: string) =>
  Math.max(0, Math.round((Date.parse(today) - Date.parse(r.createdAt.slice(0, 10))) / 86_400_000))
